@js:
var els = result.select("h3 a, .post-title a");
var map = {};
var list = [];
for (var i = 0; i < els.size(); i++) {
  var a = els.get(i);
  var t = String(a.text() || "").trim();
  if (!t) continue;
  var name = t
    .replace(/\s*第\s*\d+\s*[章节卷集].*$/g, "")
    .replace(/\s*第[一二三四五六七八九十百千万零两\d]+[章节卷集].*$/g, "")
    .replace(/\s*内容简介.*$/g, "")
    .replace(/\s*-\s*长篇.*$/g, "")
    .trim();
  if (!name || name.length < 2) continue;
  if (map[name]) continue;
  map[name] = true;
  list.push({
    name: name,
    bookUrl: "https://book.xbookcn.net/search/label/" + encodeURIComponent(name) + "?max-results=500"
  });
}
list;

