ruleExplore.bookList:
@js:
let html = typeof result === "string" ? result : String(result);
try {
  if (result && result.outerHtml) html = result.outerHtml();
} catch (e) {}

const doc = org.jsoup.Jsoup.parse(html, baseUrl);
const list = [];
const kind = `长篇, ${doc.select(".post-body").first()?.text().trim() || ""}`;
const all = doc.select(".post-body").select("h3, a[href*='/search/label/']");
let author = "";

for (let i = 0; i < all.size(); i++) {
  const el = all.get(i);
  const tagName = String(el.tagName() || "").toLowerCase();

  if (tagName === "h3") {
    author = (el.text() || "").trim();
    continue;
  }

  const name = String(el.attr("title") || el.text() || "")
    .replace(/[《》]/g, "")
    .trim();
  const parentText = String(el.parent()?.text() || "").trim();
  author = (String(parentText).match(/作者[：:]\s*([^\s\n\r，,。]+)/) || [])[1] || author

  const bookUrl = String(el.attr("href") || "");
  if (!bookUrl) continue;

  if (bookUrl.indexOf("http") !== 0) {
    bookUrl = baseUrl + (bookUrl.charAt(0) === "/" ? bookUrl : "/" + bookUrl);
  }

  list.push({
    name,
    author,
    bookUrl,
    kind,
  });
}

list;

ruleToc.chapterList:
@js:
let url = baseUrl;
let list = [];
let isFirstPage = true;

while (url) {
    const pageHtml = java.ajax(url);
    const doc = org.jsoup.Jsoup.parse(pageHtml)
    let tocs = doc.select("h3.post-title.entry-title a");

    if (isFirstPage) {
        isFirstPage = false;
        const firstToc = tocs.first();
        if(firstToc.text().indexOf("内容简介") === -1) {
            tocs = tocs.not(firstToc);
        }
    }

    list.push(...tocs);

    // 获取下一页
    const next = doc.select("a.blog-pager-older-link").attr("href");

    if (!next) {
        break;
    }

    // 防止跳到其他标签
    if (next.indexOf(baseUrl) === -1) {
        break;
    }

    url = next;
}



list.join("\n");

