var doc = org.jsoup.Jsoup.parse(result);   // 先把字符串转成 Document
var imgs = doc.select("img.comic_img, img.lazy, img");
var html = "";
for (var i = 0; i < imgs.size(); i++) {
  var src = imgs.get(i).attr("data-original") 
         || imgs.get(i).attr("data-src") 
         || imgs.get(i).attr("src");
  if (src && src.indexOf("http") === 0) {
    html += "<img src=\"" + src + "\">\n";
  }
}
html;

